// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    Rejector helper;

    function setUp() public { c = new Reentrance(); helper = new Rejector(); }

    function testFuzz_property(uint256 amount, uint256 seed) public {
        vm.assume(amount <= VALUE_CAP);
        // amount is the positive balance withdrawn; keep it admissible (no overflow in addToBalance)
        amount = bound(amount, 1, 1 ether);
        seed;

        // the actor is the helper itself: it both deposits and is the withdrawal recipient
        vm.deal(address(helper), amount);
        vm.prank(address(helper));
        c.addToBalance{value: amount}();

        // reference: withdrawBalance sends `amount` out; helper rejects ether -> low-level call
        // fails -> withdrawBalance reverts. Mutant sends 0 -> helper accepts -> call succeeds.
        bool ok;
        vm.prank(address(helper));
        try c.withdrawBalance() { ok = true; } catch { ok = false; }

        assertTrue(!ok, "withdrawal to an ether-rejecting recipient must revert");
    }
}

contract Rejector {
    receive() external payable {
        if (msg.value > 0) revert();
    }
}
